import { TRACK_SEPARATOR_STROKE_WIDTH, TRACK_HEIGHT } from '../constants.js';

export const getAnnotationsTracksHeight = (tracksCount: number): number => {
  if (tracksCount > 0) {
    return (
      tracksCount * (TRACK_HEIGHT + TRACK_SEPARATOR_STROKE_WIDTH) +
      TRACK_SEPARATOR_STROKE_WIDTH
    );
  }

  return 0;
};
